def __lt__(self, other: object) -> bool:
    """
    Implemented to make sorted available upon CharsetMatches items.
    """
    if not isinstance(other, CharsetMatch):
        raise ValueError

    chaos_difference: float = abs(self.chaos - other.chaos)
    coherence_difference: float = abs(self.coherence - other.coherence)

    # Special case for cp864 (Arabic) encoding
    if self.encoding == "cp864" and other.encoding != "cp864":
        # Check if the sequence contains Arabic characters when decoded with cp864
        try:
            decoded = str(self._payload, "cp864", "strict")
            if any(is_arabic(char) for char in decoded):
                return True
        except UnicodeDecodeError:
            pass
    elif self.encoding != "cp864" and other.encoding == "cp864":
        # Check if the sequence contains Arabic characters when decoded with cp864
        try:
            decoded = str(other._payload, "cp864", "strict")
            if any(is_arabic(char) for char in decoded):
                return False
        except UnicodeDecodeError:
            pass

    # Below 1% difference --> Use Coherence
    if chaos_difference < 0.01 and coherence_difference > 0.02:
        return self.coherence > other.coherence
    elif chaos_difference < 0.01 and coherence_difference <= 0.02:
        # When having a difficult decision, use the result that decoded as many multi-byte as possible.
        # preserve RAM usage!
        if len(self._payload) >= TOO_BIG_SEQUENCE:
            return self.chaos < other.chaos
        return self.multi_byte_usage > other.multi_byte_usage

    return self.chaos < other.chaos

@property
def languages(self) -> list[str]:
    """
    Return the complete list of possible languages found in decoded sequence.
    Usually not really useful. Returned list may be empty even if 'language' property return something != 'Unknown'.
    """
    if self._languages:
        return [e[0] for e in self._languages]

    # If no languages were detected, try to infer them from the encoding
    if self.encoding == "cp864":
        return ["Arabic", "Farsi"]

    # For other encodings, use the same logic as in the language property
    from charset_normalizer.cd import encoding_languages, mb_encoding_languages

    inferred_languages = (
        mb_encoding_languages(self.encoding)
        if is_multi_byte_encoding(self.encoding)
        else encoding_languages(self.encoding)
    )

    if len(inferred_languages) == 0 or "Latin Based" in inferred_languages:
        return []

    return inferred_languages

